import UIKit

private let log = DebugLog.create("silk-videoplayer")

private let kvoContext = UnsafeMutablePointer<()>()

/**
 * Video player that plays DASH segments generated by Silk device
 */
public class DashSegmentPlayer : UIView, VBPlayerDelegate {

  public var onCanPlay: RCTDirectEventBlock?
  public var onPlay: RCTDirectEventBlock?
  public var onPause: RCTDirectEventBlock?
  public var onWaiting: RCTDirectEventBlock?
  public var onPlaying: RCTDirectEventBlock?
  public var onTimeUpdate: RCTDirectEventBlock?
  public var onError: RCTDirectEventBlock?

  private var bridge: RCTBridge!

  private var player: VBDataPlayer?
  private var playerLayer: VBDisplayLayer?
  private var playing = false
  private let playback = DashSegmentPlayback()

  private var timeObserver: AnyObject?

  private let methodQueue = dispatch_queue_create("com.silklabs.videoplayer", nil)

  init(bridge: RCTBridge) {
    super.init(frame: CGRectZero)
    self.bridge = bridge
  }

  override init(frame: CGRect) {
    NOT_IMPLEMENTED()
    super.init(frame: frame)
  }

  required public init?(coder aDecoder: NSCoder) {
    NOT_IMPLEMENTED()
    super.init(coder: aDecoder)
  }

  deinit {
    self.destroy()
  }

  func destroy() {
    if let player = self.player {
      player.removeObserver(self, forKeyPath: "status", context: kvoContext)
      if let timeObserver = self.timeObserver {
        player.removeTimeObserver(timeObserver)
      }
    }
    self.player = nil
    self.playerLayer = nil
    self.bridge = nil
  }

  private func initializePlayer() {
    self.playerLayer = VBDisplayLayer()
    self.playerLayer!.frame = self.bounds
    self.layer.addSublayer(self.playerLayer!)

    self.player = VBDataPlayer.createDataPlayer()
    self.player!.delegate = self
    self.player!.setDisplayLayer(self.playerLayer!)

    self.player!.addObserver(self, forKeyPath: "status", options: .New, context: kvoContext)
    self.timeObserver = self.player!.addPeriodicTimeObserverForInterval(
      CMTimeMake(250, 1000),
      queue: self.methodQueue,
      usingBlock: {
        if let onTimeUpdate = self.onTimeUpdate,
          player = self.player {
          onTimeUpdate([
            "currentTime": CMTimeGetSeconds(player.currentTime),
            "buffered": CMTimeGetSeconds(player.bufferedDuration()),
          ])
        }
      }
    )
  }

  func play() {
    AssertMainThread()
    if (self.player == nil) {
      self.initializePlayer()
      return;
    }

    if self.playing || self.player!.status != .ReadyToPlay {
      return
    }

    self.player!.play()
    self.playing = true

    if let onPlay = self.onPlay {
      onPlay(nil)
    }
    if let onPlaying = self.onPlay {
      onPlaying(nil)
    }
  }

  public override func observeValueForKeyPath(
    keyPath: String?,
    ofObject object: AnyObject?,
    change: [String : AnyObject]?,
    context: UnsafeMutablePointer<Void>
  ) {
    if (context != kvoContext) {
      return
    }
    switch (self.player!.status) {
    case .Unknown:
      break
    case .ReadyToPlay:
      if let onCanPlay = self.onCanPlay {
        onCanPlay(nil)
      }
      break
    case .Failed:
      self.dispatchErrorEvent(self.player!.error.localizedDescription)
      break
    }
  }

  func pause() {
    if self.playing {
      // If we are already playing a simple pause works...
      self.player!.pause()
      self.playing = false
      // Note: we _could_ reset playback rate here but that would defeat the purpose of trying
      // to give JS as much control as possible.
    }
  }

  func enqueue(segment: VideoSegment) {
    AssertMainThread()
    if (self.player == nil) {
      self.initializePlayer()
    }

    dispatch_async(self.methodQueue) {
      let blobManager = self.bridge.moduleForClass(BlobManager) as! BlobManager
      let rawData = blobManager.resolveAndReleaseBlob(segment.blob!)
      guard
        rawData != nil
      else {
        self.dispatchErrorEvent("Could not resolve blob \(segment.blob)")
        return
      }
      let data: NSData
      do {
        data = try self.playback.processSegment(NSMutableData(data: rawData!))
        try self.player!.appendData(data, coding: .MP4)
      } catch {
        self.dispatchErrorEvent("Processing mp4 segment failed")
        return
      }
    }
  }

  private func dispatchErrorEvent(errorMessage: String) {
    if let onError = self.onError {
      onError(["error": errorMessage])
    }
  }

  // VBPlayerDelegate

  public func playerDidEnterStall(player: VBPlayer!) {
    if let onWaiting = self.onWaiting {
      onWaiting(nil)
    }
  }

  public func playerDidExitStall(player: VBPlayer!) {
    if let onPlaying = self.onPlaying {
      onPlaying(nil)
    }
  }

  public func playerDidFinish(player: VBPlayer!) {
    // We don't really care.
  }
}